# 1. Port check on 192.168.10.1
$ports = @(21, 22, 23, 53, 80, 443, 2000, 8080, 8291, 8728, 8729)
foreach ($p in $ports) {
    $tcp = New-Object System.Net.Sockets.TcpClient
    $connect = $tcp.BeginConnect("192.168.10.1", $p, $null, $null)
    $wait = $connect.AsyncWaitHandle.WaitOne(400, $false)
    if ($wait -and $tcp.Connected) {
        Write-Host "Port $p : OPEN"
    } else {
        Write-Host "Port $p : CLOSED"
    }
    $tcp.Close()
}

# 2. HTTP WebFig check
try {
    $resp = Invoke-WebRequest -Uri "http://192.168.10.1" -UseBasicParsing -TimeoutSec 3
    Write-Host "HTTP Status: $($resp.StatusCode)"
    $resp.Content.Substring(0, [Math]::Min(1000, $resp.Content.Length))
} catch {
    Write-Host "HTTP error: $_"
}

# 3. MNDP Discovery (UDP 5678)
try {
    $udp = New-Object System.Net.Sockets.UdpClient(5678)
    $udp.Client.ReceiveTimeout = 3000
    $ep = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Broadcast, 5678)
    $bytes = [byte[]](0,0,0,0)
    $udp.Send($bytes, $bytes.Length, "255.255.255.255", 5678) | Out-Null
    $udp.Send($bytes, $bytes.Length, "192.168.10.255", 5678) | Out-Null
    $udp.Send($bytes, $bytes.Length, "192.168.10.1", 5678) | Out-Null
    $start = Get-Date
    while (((Get-Date) - $start).TotalSeconds -lt 4) {
        $remoteEp = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
        $data = $udp.Receive([ref]$remoteEp)
        if ($data.Length -gt 4) {
            Write-Host "MNDP Packet from $($remoteEp.Address) ($($data.Length) bytes):"
            $pos = 4
            while ($pos + 4 -le $data.Length) {
                $type = [BitConverter]::ToUInt16($data, $pos)
                if ([BitConverter]::IsLittleEndian) {
                    $type = [uint16](($data[$pos] -shl 8) -bor $data[$pos+1])
                    $len = [uint16](($data[$pos+2] -shl 8) -bor $data[$pos+3])
                }
                $pos += 4
                if ($pos + $len -le $data.Length) {
                    $valBytes = $data[$pos..($pos+$len-1)]
                    $strVal = [System.Text.Encoding]::ASCII.GetString($valBytes)
                    $hexVal = ($valBytes | ForEach-Object { $_.ToString("X2") }) -join ":"
                    Write-Host "  TLV Type $type (len $len): ASCII='$strVal' HEX=$hexVal"
                }
                $pos += $len
            }
        }
    }
    $udp.Close()
} catch {
    Write-Host "MNDP finished/timeout: $_"
    if ($udp) { $udp.Close() }
}

