try {
    $localEp = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Parse("192.168.10.228"), 5678)
    $udp = New-Object System.Net.Sockets.UdpClient($localEp)
    $udp.EnableBroadcast = $true
    $udp.Client.ReceiveTimeout = 3000
    $bytes = [byte[]](0,0,0,0)
    $udp.Send($bytes, $bytes.Length, "255.255.255.255", 5678) | Out-Null
    for ($i = 0; $i -lt 5; $i++) {
        $remoteEp = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
        $data = $udp.Receive([ref]$remoteEp)
        if ($data.Length -gt 4) {
            Write-Host "Received MNDP from $($remoteEp.Address) ($($data.Length) bytes)"
            $pos = 4
            while ($pos + 4 -le $data.Length) {
                $type = [uint16](($data[$pos] -shl 8) -bor $data[$pos+1])
                $len = [uint16](($data[$pos+2] -shl 8) -bor $data[$pos+3])
                $pos += 4
                if ($pos + $len -le $data.Length -and $len -gt 0) {
                    $valBytes = $data[$pos..($pos+$len-1)]
                    $strVal = [System.Text.Encoding]::UTF8.GetString($valBytes)
                    $hexVal = ($valBytes | ForEach-Object { $_.ToString("X2") }) -join ":"
                    Write-Host ("  TLV {0,2} (len {1,2}): ASCII='{2}' | HEX={3}" -f $type, $len, $strVal, $hexVal)
                }
                $pos += $len
            }
        }
    }
    $udp.Close()
} catch {
    if ($udp) { $udp.Close() }
}

