try {
    $tcp = New-Object System.Net.Sockets.TcpClient("192.168.10.1", 8728)
    $stream = $tcp.GetStream()
    $stream.ReadTimeout = 2000
    function Send-RosWord($s, [string]$w) {
        $b = [System.Text.Encoding]::UTF8.GetBytes($w)
        $s.WriteByte([byte]$b.Length)
        $s.Write($b, 0, $b.Length)
    }
    Send-RosWord $stream "/login"
    Send-RosWord $stream "=name=admin"
    Send-RosWord $stream "=password="
    $stream.WriteByte(0)
    $buf = New-Object byte[] 512
    $read = $stream.Read($buf, 0, 512)
    $reply = [System.Text.Encoding]::ASCII.GetString($buf, 0, $read)
    Write-Host "API Login Reply ($read bytes): $reply"
    $tcp.Close()
} catch {
